    function showToast(msg) {
      const toast = document.getElementById('toast');
      toast.innerText = msg;
      toast.classList.add('show');
      setTimeout(() => { toast.classList.remove('show'); }, 2200);
    }

    function setTheme(theme) {
      document.documentElement.setAttribute('data-theme', theme);
      localStorage.setItem('sk_theme', theme);
      showToast("Theme applied: " + theme.toUpperCase());
    }

    function adjustThemeDepth(val) {
      const depthFactor = val / 100;
      document.documentElement.style.setProperty('--glass-shadow', `0 4px ${14 * depthFactor}px rgba(37, 99, 235, ${0.12 * depthFactor})`);
      const label = document.getElementById('depthValueLabel');
      if (label) label.innerText = val + '%';
      localStorage.setItem('sk_theme_depth', val);
    }

    function resetThemeToDefault() {
      setTheme('light');
      localStorage.removeItem('sk_theme');
      localStorage.removeItem('sk_theme_depth');
      const slider = document.getElementById('themeDepthSlider');
      if (slider) slider.value = 100;
      adjustThemeDepth(100);
      showToast("Theme reset to Classic Light Default!");
    }

    function openItemEditor() {
      toggleModal('itemEditorModal', true);
    }

    function handleExcelFileUpload(input) {
      if (input.files && input.files[0]) {
        const file = input.files[0];
        const reader = new FileReader();
        reader.onload = function (e) {
          try {
            const data = new Uint8Array(e.target.result);
            const workbook = XLSX.read(data, { type: 'array' });
            const firstSheetName = workbook.SheetNames[0];
            const worksheet = workbook.Sheets[firstSheetName];
            const jsonRows = XLSX.utils.sheet_to_json(worksheet, { header: 1 });

            if (jsonRows.length < 1) {
              showToast("Excel file is empty!");
              return;
            }

            let addedCount = 0;
            for (let i = 0; i < jsonRows.length; i++) {
              const row = jsonRows[i];
              if (!row || row.length === 0) continue;

              let models = [];
              row.forEach(cell => {
                if (cell) {
                  let val = String(cell).trim();
                  if (val) {
                    let parts = val.split(/,|\n|\|/);
                    parts.forEach(p => {
                      if (p.trim()) models.push(p.trim());
                    });
                  }
                }
              });

              if (models.length > 0) {
                let titleModels = models.slice(0, 4);
                let title = titleModels.join(' / ');
                if (models.length > 4) title += ' / ...';

                const newItem = {
                  id: `SK-EXC-${Date.now().toString().slice(-4)}_${i}`,
                  title,
                  category: "glass",
                  subType: "11d",
                  spec: "Universal",
                  stock: 15,
                  ordered: false,
                  note: "Imported via Excel Models",
                  models
                };
                inventory.unshift(newItem);
                addedCount++;
              }
            }

            saveInventory();
            renderCards();
            toggleModal('itemEditorModal', false);
            showToast(`Successfully imported ${addedCount} items from Excel!`);
          } catch (err) {
            showToast("Failed to parse Excel file.");
          }
        };
        reader.readAsArrayBuffer(file);
      }
    }

    function saveManualInventoryItem() {
      let title = document.getElementById('editItemTitle').value.trim();
      const category = document.getElementById('editItemCategory').value;
      const stock = parseInt(document.getElementById('editItemStock').value) || 15;
      const modelsRaw = document.getElementById('editItemModels').value.trim();
      const models = modelsRaw.split(/,|\n|\|/).map(m => m.trim()).filter(Boolean);

      if (models.length === 0) {
        showToast("Models are required!");
        return;
      }

      if (!title) {
        let titleModels = models.slice(0, 4);
        title = titleModels.join(' / ');
        if (models.length > 4) title += ' / ...';
      }

      const newItem = {
        id: `SK-M-${Date.now().toString().slice(-4)}`,
        title,
        category,
        subType: category === 'combo' ? 'combo' : '11d',
        spec: 'Universal',
        stock,
        ordered: false,
        note: 'Manually Added Item',
        models
      };
      inventory.unshift(newItem);
      saveInventory();
      renderCards();
      toggleModal('itemEditorModal', false);
      showToast("New item added successfully!");
    }

