  const DEFAULT_FIREBASE_CONFIG={apiKey:'AIzaSyDufQNy7l9M3ue_32u3gcH3TZUhPlrSILA',authDomain:'sk-mobiles-2d61d.firebaseapp.com',projectId:'sk-mobiles-2d61d',storageBucket:'sk-mobiles-2d61d.firebasestorage.app',messagingSenderId:'705961182597',appId:'1:705961182597:web:fa8238739d140b250df0ec'};
  function cfg(){try{return {...DEFAULT_FIREBASE_CONFIG,...JSON.parse(localStorage.getItem(CFG_KEY)||'{}')}}catch(e){return {...DEFAULT_FIREBASE_CONFIG}}}
